const MESES = ['janeiro','fevereiro','marco','abril','maio','junho','julho','agosto','setembro','outubro','novembro','dezembro'];
const state = {
  loading: true, error: '', authMode: 'login', authEmail: '', authPass: '', authName: '', authTeam: '',
  user: null, profile: null, view: 'form', records: [], period: 'semana', filterTurn: 'Todos',
  filterTeam: 'Todas as equipes', refDate: today(), saved: false, form: emptyForm(), formTab:'identificacao', editing:null,dirty:false,saving:false,authBusy:false,recordsLoading:false,recordsError:'',teams:[],defaults:null,groups:[],groupsTeam:'',groupsVersion:'',preferencesBusy:false,notice:'',securityUsers:[],securityEvents:[],securityCount:0,securityOffset:0,securityLoading:false,securityBusy:false,securityError:'',auditRecord:null,auditEvents:[],auditLoading:false
};

function today(){const parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const get=t=>parts.find(p=>p.type===t).value;return `${get('year')}-${get('month')}-${get('day')}`}
function emptyForm(){return{data:today(),turno:'Diurno',equipe:'',coordenador:'',integrantes:[''],faltas:[{nome:'',motivo:''}],dia:[{texto:'',status:'Aberto',responsavel:''}],proximo:[{texto:'',status:'Aberto',responsavel:''}],ocorrencias:[{hora:'',gravidade:'Baixa',texto:''}],fechamento:null}}
function esc(v){return String(v??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
function clean(a){return(a||[]).map(x=>String(x).trim()).filter(Boolean)}
function taskText(x){return typeof x==='string'?x:String(x?.texto||'')}
function taskStatus(x){return ['Aberto','Em andamento','Resolvido'].includes(x?.status)?x.status:'Aberto'}
function taskOwner(x){return String(x?.responsavel||'').trim()}
function cleanTasks(a){return(a||[]).map(x=>({texto:taskText(x).trim(),status:taskStatus(x),responsavel:taskOwner(x)})).filter(x=>x.texto)}
function taskCount(a,status){const rows=cleanTasks(a);return status?rows.filter(x=>x.status===status).length:rows.length}
function closedLabel(r){return r?.fechamento?.em?'Fechado':'Aberto'}
function parseDate(iso){const[y,m,d]=String(iso||'').split('-').map(Number);return new Date(y||1970,(m||1)-1,d||1)}
function isoDate(d){return`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function shortDate(iso){const[y,m,d]=String(iso||'').split('-');return d?`${d}/${m}/${String(y).slice(2)}`:'-'}
function longDate(iso){const[y,m,d]=String(iso||'').split('-');return d?`${d} de ${MESES[Number(m)-1]} de ${y}`:'Data nao informada'}
function isChief(){return state.profile?.perfil === 'Chefia'}
function setValue(path,value){if(path==='refDate' && (!/^\d{4}-\d{2}-\d{2}$/.test(value)||isoDate(parseDate(value))!==value))return;const p=path.split('.');let t=state;while(p.length>1)t=t[p.shift()];t[p[0]]=value;if(['period','refDate'].includes(path)){state.filterTeam='Todas as equipes';void loadRecords()}render()}
function setForm(path,value){state.form[path]=value;markDirty();render()}
function addList(k,v){state.form[k].push(v);markDirty();render()}
function removeList(k,i){markDirty();state.form[k]=state.form[k].filter((_,j)=>j!==i);if(!state.form[k].length)state.form[k].push(k==='ocorrencias'?{hora:'',gravidade:'Baixa',texto:''}:k==='faltas'?{nome:'',motivo:''}:'');render()}

let sessionVersion = 0;
let recordsVersion = 0;

function resetSession(){
  sessionVersion++;
  recordsVersion++;
  Object.assign(state,{user:null,profile:null,authPass:'',authEmail:'',authName:'',authTeam:'',
    records:[],form:emptyForm(),view:'form',saved:false,error:'',editing:null,dirty:false,
    saving:false,authBusy:false,recordsLoading:false,recordsError:'',teams:[],defaults:null,groups:[],groupsTeam:'',groupsVersion:'',preferencesBusy:false,notice:'',securityUsers:[],securityEvents:[],securityCount:0,securityOffset:0,securityLoading:false,securityBusy:false,securityError:'',auditRecord:null,auditEvents:[],auditLoading:false,filterTurn:'Todos',
    filterTeam:'Todas as equipes',period:'semana',refDate:today()});
}

let csrfToken = '';
let expiryTimer;
let serverUnavailable = false;
const accountChannel = typeof BroadcastChannel !== 'undefined' ? new BroadcastChannel('plantao-account') : null;

async function api(path,options={}){
  const version=sessionVersion;
  let response;
  try{response=await fetch('/api'+path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json','X-CSRF-Token':csrfToken,...options.headers}})}
  catch(error){throw new Error('Nao foi possivel conectar ao servidor. Tente novamente.')}
  let data;
  try{data=await response.json()}catch(error){throw new Error('O servidor do sistema esta indisponivel.')}
  if(!response.ok){
    if(response.status===401 && path!=='/login' && version===sessionVersion){resetSession();state.loading=false;state.error='Sua sessao expirou. Entre novamente.';render()}
    throw new Error(data.error||'Nao foi possivel concluir a operacao.');
  }
  return data;
}

async function acceptSession(session){
  csrfToken=session.csrf;
  clearTimeout(expiryTimer);
  if(session.user){
    expiryTimer=setTimeout(()=>{resetSession();state.loading=false;state.error='Sua sessao expirou. Entre novamente.';render();void init()},Math.max(0,session.expires-Date.now()));
  }
  if(session.user?.id===state.user?.id && state.profile){state.profile=session.user;state.teams=session.teams;state.defaults=session.defaults||null;return}
  resetSession();
  if(!session.user){state.loading=false;render();return}
  state.user={id:session.user.id};state.profile=session.user;state.teams=session.teams;
  state.defaults=session.defaults||null;applyDefaults();
  state.loading=true;
  const version=sessionVersion;
  await loadRecords();
  if(version===sessionVersion){state.loading=false;render()}
}
async function init(){
  const version=sessionVersion;
  try{
    const session=await api('/session');
    if(version!==sessionVersion)return;
    serverUnavailable=false;await acceptSession(session);
  }catch(error){if(version===sessionVersion){serverUnavailable=true;state.loading=false;state.error=error.message;render()}}
}
async function loadRecords(){
  if(!state.user || !state.profile)return;
  const session=sessionVersion,request=++recordsVersion;
  const [start,end]=windowDates().map(isoDate);
  state.recordsLoading=true;state.recordsError='';state.records=[];
  const rows=[];
  try{
    let offset=0;
    while(true){
      const {data,count}=await api(`/reports?start=${start}&end=${end}&offset=${offset}`);
      if(session!==sessionVersion || request!==recordsVersion)return;
      if(!Array.isArray(data))throw new Error('Resposta invalida');
      rows.push(...data);offset+=data.length;
      if(count!==null && count!==undefined && offset>=count)break;
      if(!data.length){if(count>offset)throw new Error('Consulta incompleta');break}
    }
    state.records=rows;
  }catch(error){
    if(session===sessionVersion && request===recordsVersion){state.records=[];state.recordsError='Nao foi possivel carregar o periodo completo. Tente novamente.'}
  }finally{
    if(session===sessionVersion && request===recordsVersion){state.recordsLoading=false;render()}
  }
}

async function loginOrSignup(){
  if(state.authBusy)return;
  state.error='';
  const email=state.authEmail.trim().toLowerCase(),password=state.authPass;
  if(!email||!password){state.error='Informe e-mail ou login e senha.';render();return}
  state.authBusy=true;
  const version=sessionVersion;
  try{
    if(state.authMode==='access'){
      await api('/register',{method:'POST',body:JSON.stringify({email,password,nome:state.authName,equipe:state.authTeam})});
      if(version!==sessionVersion)return;
      state.authMode='login';
      state.notice='Solicitação enviada. Aguarde a aprovação da Chefia para entrar.';
      render();return;
    }
    const session=await api('/login',{method:'POST',body:JSON.stringify({email,password})});
    if(version!==sessionVersion)return;
    await acceptSession(session);
    accountChannel?.postMessage('changed');
  }catch(error){if(version===sessionVersion)state.error=error.message}
  finally{state.authPass='';state.authBusy=false;render()}
}
async function logout(){
  if(state.dirty && !confirm('Sair e descartar as alteracoes nao salvas?'))return;
  resetSession();clearTimeout(expiryTimer);state.loading=false;render();
  try{
    await api('/logout',{method:'POST',body:'{}'});
    csrfToken='';accountChannel?.postMessage('changed');await init();
  }catch(error){state.error='Nao foi possivel encerrar a sessao. Tente sair novamente antes de compartilhar este computador.';render()}
}

function recordPayload(){
  const f=state.form;
  if(!/^\d{4}-\d{2}-\d{2}$/.test(f.data) || isoDate(parseDate(f.data))!==f.data)throw new Error('Informe uma data valida.');
  if(!['Diurno','Noturno'].includes(f.turno))throw new Error('Informe o turno.');
  if(!f.equipe.trim())throw new Error('Informe uma equipe autorizada.');
  if(!isChief() && !state.teams.includes(f.equipe.trim()))throw new Error('Solicite a liberacao desta equipe pela Chefia.');
  const faltas=(f.faltas||[]).filter(x=>String(x.nome||'').trim());
  const ocorrencias=(f.ocorrencias||[]).filter(x=>String(x.texto||'').trim());
  if(ocorrencias.some(o=>!['Baixa','Media','Alta'].includes(o.gravidade) || (o.hora && !/^([01]\d|2[0-3]):[0-5]\d$/.test(o.hora))))throw new Error('Confira horario e gravidade das ocorrencias.');
  return {data:f.data,turno:f.turno,equipe:f.equipe.trim(),coordenador:f.coordenador.trim(),
    integrantes:clean(f.integrantes),faltas:faltas.map(x=>({nome:x.nome.trim(),motivo:String(x.motivo||'').trim()})),
    dia:cleanTasks(f.dia),proximo:cleanTasks(f.proximo),ocorrencias:ocorrencias.map(o=>({hora:o.hora,gravidade:o.gravidade,texto:o.texto.trim()})),fechamento:f.fechamento||null};
}

async function saveRecord(closeAfterSave=false){
  if(!state.user || !state.profile || state.saving)return;
  const version=sessionVersion;
  state.saving=true;state.error='';state.saved=false;
  try{
    const payload=recordPayload(),snapshot=JSON.stringify(state.form);
    const data=state.editing
      ?await api('/reports/'+encodeURIComponent(state.editing.id),{method:'PUT',body:JSON.stringify({...payload,updated_at:state.editing.updated_at,fechar:closeAfterSave})})
      :await api('/reports',{method:'POST',body:JSON.stringify({...payload,fechar:closeAfterSave})});
    if(version!==sessionVersion)return;
    state.form.assinatura=data.assinatura;if(closeAfterSave)state.form.fechamento=data.assinatura;state.editing=data;state.dirty=closeAfterSave?false:JSON.stringify({...state.form,assinatura:undefined})!==JSON.stringify({...JSON.parse(snapshot),assinatura:undefined});state.saved=!state.dirty;
    await loadRecords();
  }catch(error){if(version===sessionVersion)state.error=error.message}
  finally{if(version===sessionVersion){state.saving=false;render()}}
}

async function closeRecord(){if(!state.editing&&!confirm('Salvar e fechar este plantão agora?'))return;if(state.form.fechamento?.em){state.error='Este plantão já está fechado.';render();return}if(confirm('Fechar o plantão? Depois disso, Supervisores não poderão editar nem excluir.'))await saveRecord(true)}
function clearForm(){
  if(state.saving)return;
  if(state.dirty && !confirm('Descartar as alteracoes nao salvas?'))return;
  state.form=emptyForm();applyDefaults();
  state.editing=null;state.dirty=false;state.saved=false;state.error='';state.view='form';render();
}
function openRecord(id){
  if(state.saving)return;
  const row=state.records.find(r=>r.id===id);if(!row)return;
  if(state.dirty && !confirm('Descartar as alterações não salvas e abrir este plantão?'))return;
  state.form=JSON.parse(JSON.stringify(Object.fromEntries(Object.keys(emptyForm()).map(k=>[k,row[k]]))));
  for(const key of ['integrantes','dia','proximo'])if(!state.form[key].length)state.form[key]=[''];
  if(!state.form.faltas.length)state.form.faltas=[{nome:'',motivo:''}];
  if(!state.form.ocorrencias.length)state.form.ocorrencias=[{hora:'',gravidade:'Baixa',texto:''}];
  state.form.dia=(state.form.dia||[]).map(x=>typeof x==='string'?{texto:x,status:'Aberto',responsavel:''}:x);
  state.form.proximo=(state.form.proximo||[]).map(x=>typeof x==='string'?{texto:x,status:'Aberto',responsavel:''}:x);
  state.form.assinatura=row.assinatura;state.form.fechamento=row.fechamento||null;state.editing={id:row.id,updated_at:row.updated_at};state.dirty=false;state.saved=false;state.error='';state.view='form';render();
}

async function openAudit(id){if(!isChief())return;const row=state.records.find(r=>r.id===id);if(!row)return;const version=sessionVersion;state.auditRecord=row;state.auditEvents=[];state.auditLoading=true;state.error='';render();try{const events=await api('/reports/'+encodeURIComponent(id)+'/audit');if(version===sessionVersion){state.auditEvents=events;state.auditLoading=false;render()}}catch(e){if(version===sessionVersion){state.auditLoading=false;state.error=e.message;render()}}}
function auditSummary(event){const before=event.previous_data?JSON.parse(event.previous_data):null,next=event.next_data?JSON.parse(event.next_data):null;if(event.operation==='INSERT')return 'Plantão criado';if(event.operation==='DELETE')return 'Plantão excluído';if(!before?.fechamento?.em&&next?.fechamento?.em)return 'Plantão fechado';const changes=[];if(before&&next){if(before.coordenador!==next.coordenador)changes.push('coordenador');if(JSON.stringify(before.dia)!==JSON.stringify(next.dia))changes.push('demandas');if(JSON.stringify(before.proximo)!==JSON.stringify(next.proximo))changes.push('repasses');if(JSON.stringify(before.ocorrencias)!==JSON.stringify(next.ocorrencias))changes.push('ocorrências');if(JSON.stringify(before.faltas)!==JSON.stringify(next.faltas))changes.push('faltas');if(before.equipe!==next.equipe)changes.push('equipe');}return changes.length?'Atualizado: '+changes.join(', '):'Plantão atualizado'}
function auditPanel(){if(!state.auditRecord)return '';return `<div class="modal-backdrop no-print" onclick="if(event.target===this){state.auditRecord=null;render()}"><section class="modal-card"><div class="pane-header"><div><div class="kicker">Auditoria do plantão</div><h2>${shortDate(state.auditRecord.data)} · ${esc(state.auditRecord.turno)} · ${esc(state.auditRecord.equipe||'-')}</h2></div><button onclick="state.auditRecord=null;render()">Fechar</button></div>${state.auditLoading?'<p>Carregando histórico...</p>':state.auditEvents.length?`<table><thead><tr><th>Data</th><th>Ação</th><th>Responsável</th></tr></thead><tbody>${state.auditEvents.map(e=>`<tr><td>${esc(new Date(e.occurred_at).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}))}</td><td>${esc(auditSummary(e))}</td><td>${esc(e.actor_nome||e.actor_email||'-')}</td></tr>`).join('')}</tbody></table>`:'<p class="hint">Nenhum histórico encontrado.</p>'}</section></div>`}
async function deleteRecord(id){
  if(state.saving)return;
  const row=state.records.find(r=>r.id===id);if(!row)return;
  if(!confirm(`Excluir o plantão de ${shortDate(row.data)} - ${row.turno} - ${row.equipe||'sem equipe'}?`))return;
  const version=sessionVersion;
  state.saving=true;state.error='';
  try{
    await api('/reports/'+encodeURIComponent(id),{method:'DELETE'});
    if(version!==sessionVersion)return;
    if(state.editing?.id===id){state.form=emptyForm();applyDefaults();state.editing=null;state.dirty=false;state.saved=false}
    await loadRecords();
  }catch(error){if(version===sessionVersion)state.error=error.message}
  finally{if(version===sessionVersion){state.saving=false;render()}}
}
function markDirty(){if(state.form.fechamento?.em && !isChief()){state.error='Plantão fechado. Procure a Chefia para alterar.';render();return}state.dirty=true;state.saved=false;const button=document.getElementById('save-record');if(button && !state.saving)button.textContent='Salvar plantão'}
function csvCell(value){
  let text=String(value??'');
  if(/^[\s\uFEFF]*[=+@\-\uFF1D\uFF0B\uFF20\uFF0D]/u.test(text)||/^[\t\r\n]/.test(text))text="'"+text;
  return '"'+text.replace(/"/g,'""')+'"';
}
function windowDates(){const ref=parseDate(state.refDate);if(state.period==='mes')return[new Date(ref.getFullYear(),ref.getMonth(),1),new Date(ref.getFullYear(),ref.getMonth()+1,0)];const s=new Date(ref);s.setDate(ref.getDate()-((ref.getDay()+6)%7));const e=new Date(s);e.setDate(s.getDate()+6);return[s,e]}
function periodRecords(){const[start,end]=windowDates().map(isoDate);return state.records.filter(r=>r.data>=start&&r.data<=end).filter(r=>state.filterTurn==='Todos'||r.turno===state.filterTurn).filter(r=>state.filterTeam==='Todas as equipes'||(r.equipe||'-')===state.filterTeam)}
function exportCsv(){if(!isChief()||state.recordsLoading||state.recordsError)return;const rows=periodRecords(),[start,end]=windowDates().map(isoDate),header=['data','turno','equipe','coordenador','integrantes','faltas','demandas_do_dia','proximo_plantao','ocorrencias'],cell=csvCell;const lines=rows.map(r=>[r.data,r.turno,r.equipe,r.coordenador,(r.integrantes||[]).join(' | '),(r.faltas||[]).map(f=>`${f.nome}${f.motivo?` (${f.motivo})`:''}`).join(' | '),(r.dia||[]).join(' | '),(r.proximo||[]).join(' | '),(r.ocorrencias||[]).map(o=>`${o.hora||'--'} [${o.gravidade}] ${o.texto}`).join(' | ')].map(cell).join(','));const blob=new Blob(['\ufeff'+[header.join(','),...lines].join('\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`plantoes-${start}-a-${end}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}

function setupView(){return `<main class="wrap"><h1>Conectar ao servidor</h1><p>${esc(state.error||'O servidor do sistema nao respondeu.')}</p><button onclick="init()">Tentar novamente</button></main>`}
function loginArtwork(){return `<svg class="login-art" viewBox="0 0 714 854" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><defs><radialGradient id="redGlow"><stop stop-color="#c30b00"/><stop offset="1" stop-color="#360300"/></radialGradient><pattern id="redDots" width="14" height="14" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r=".8" fill="#ee2917" opacity=".55"/></pattern><linearGradient id="redBar" x2="0" y2="1"><stop stop-color="#d70a10"/><stop offset="1" stop-color="#700300"/></linearGradient></defs><path fill="url(#redGlow)" d="M0 0h714v854H0z"/><path fill="url(#redDots)" d="M478 0h236v120H478zM236 510h478v300H236z"/><circle cx="500" cy="228" r="151" fill="none" stroke="#bd160b" opacity=".6"/><g fill="#430400" fill-opacity=".65" stroke="#ae160b"><rect x="432" y="127" width="281" height="164" rx="14"/><rect x="478" y="306" width="230" height="149" rx="13"/><rect x="470" y="470" width="238" height="99" rx="12"/></g><circle cx="514" cy="211" r="46" fill="none" stroke="#ad0000" stroke-width="24"/><circle cx="514" cy="211" r="46" fill="none" stroke="#e11018" stroke-width="24" stroke-dasharray="143 290" transform="rotate(-90 514 211)"/><g stroke="#b70b10" stroke-width="4" stroke-linecap="round">${[176,199,222,245].map(y=>`<path d="M614 ${y}h71"/><circle cx="597" cy="${y}" r="2"/>`).join('')}</g><g stroke="#8b0a06" opacity=".55">${[330,356,382,408,436].map(y=>`<path d="M498 ${y}h193"/>`).join('')}</g><path d="M498 425C518 412 515 393 539 400S558 367 583 381S611 378 630 356S654 374 668 344L686 330" fill="none" stroke="#f3212b" stroke-width="2"/><circle cx="686" cy="330" r="5" fill="#ed202b"/><g fill="#eee" font-family="Arial"><text x="484" y="496" font-size="6">TOTAL DE RELATÓRIOS</text><text x="562" y="496" font-size="6">PENDÊNCIAS</text><text x="635" y="496" font-size="6">CONCLUÍDOS</text><text x="484" y="522" font-size="18">1.248</text><text x="562" y="522" font-size="18">86</text><text x="635" y="522" font-size="18">93%</text></g><g fill="#c60910">${Array.from({length:30},(_,i)=>`<rect x="${484+Math.floor(i/10)*76+(i%10)*5.5}" y="${540-i%4}" width="3" height="${10+i%4}"/>`).join('')}</g><g fill="url(#redBar)">${[55,80,98,118,131,158,126,157].map((h,i)=>`<rect x="${384+i*42}" y="${778-h}" width="22" height="${h}"/>`).join('')}</g><path d="M350 778h357" stroke="#c62820"/></svg>`}
function authView(){const access=state.authMode==='access';return `<main class="login"><section class="login-visual" aria-label="Sistema de Relatórios">${loginArtwork()}<p class="login-eyebrow">Painel analítico</p><div class="login-title"><h1>Sistema de<br>Relatórios</h1><p class="login-description">Centralize indicadores, acompanhe<br class="desktop-break"> pendências e consolide informações<br class="desktop-break"> com clareza e agilidade.</p></div><p class="login-footer">Acesso corporativo · Relatórios · Indicadores</p></section><section class="login-panel"><div class="login-card"><div class="login-tabs"><button type="button" aria-pressed="${!access}" class="${!access?'selected':''}" onclick="state.authMode='login';render()">Entrar</button><button type="button" aria-pressed="${access}" class="${access?'selected':''}" onclick="state.authMode='access';render()">Criar conta</button></div><h2>${access?'Criar conta':'Entrar no sistema'}</h2><p class="login-intro">${access?'Solicite seu acesso. A Chefia precisa aprovar sua conta e definir a equipe.':'Use o e-mail cadastrado pela chefia do seu plantão.'}</p>${state.notice?`<p class="login-intro" role="status">${esc(state.notice)}</p>`:''}<form onsubmit="event.preventDefault();loginOrSignup()"><div class="field"><label for="login-email">E-mail ou login</label><input id="login-email" placeholder="e-mail ou login" type="text" autocomplete="username" required value="${esc(state.authEmail)}" oninput="state.authEmail=this.value"></div>${access?`<div class="field"><label for="register-name">Nome completo</label><input id="register-name" autocomplete="name" required maxlength="200" value="${esc(state.authName)}" oninput="state.authName=this.value"></div><div class="field"><label for="register-team">Equipe solicitada (sujeita à aprovação)</label><input id="register-team" placeholder="Ex.: Equipe B" required maxlength="120" value="${esc(state.authTeam)}" oninput="state.authTeam=this.value"></div><p class="login-intro">O cadastro fica pendente até a aprovação da Chefia. Informar uma equipe não libera acesso.</p>`:''}<div class="field"><label for="login-password">Senha</label><input id="login-password" placeholder="${access?'Mínimo 12 caracteres':'Digite sua senha'}" type="password" autocomplete="current-password" required ${access?'minlength="12"':''} maxlength="128" oninput="state.authPass=this.value"></div>${state.error?`<p class="error" role="alert">${esc(state.error)}</p>`:''}<div class="login-actions"><button class="primary" ${state.authBusy?'disabled':''} type="submit">${state.authBusy?'Aguarde...':access?'Criar conta':'Entrar'}</button><button class="login-link" type="button" onclick="state.authMode='${access?'login':'access'}';state.error='';render()">${access?'Já tenho conta':'Não tenho conta'}</button></div></form>${state.error.includes('encerrar a sessao')?'<button onclick="logout()">Tentar sair novamente</button>':''}</div></section></main>`}
function applyDefaults(){state.form.coordenador=state.profile?.nome||'';const d=state.defaults;state.form.equipe=d?.equipe&&(isChief()||state.teams.includes(d.equipe))?d.equipe:state.teams[0]||'';state.form.turno=d?.turno||'Diurno';state.groups=[];state.groupsTeam='';state.groupsVersion=''}
async function saveDefaults(signature=state.defaults?.signature||''){
 if(state.preferencesBusy)return;const version=sessionVersion;state.preferencesBusy=true;state.error='';
 try{const result=await api('/defaults',{method:'PUT',body:JSON.stringify({equipe:state.form.equipe,turno:state.form.turno,signature})});if(version!==sessionVersion)return;state.defaults=result;state.notice='Preferências salvas para os próximos plantões.'}
 catch(e){if(version===sessionVersion)state.error=e.message}finally{if(version===sessionVersion){state.preferencesBusy=false;render()}}
}
async function uploadSignature(input){const file=input.files?.[0];if(!file)return;const version=sessionVersion;if(file.type!=='image/png'||file.size>130000){state.error='Selecione uma assinatura PNG de até 130 KB.';render();return}const reader=new FileReader();reader.onload=()=>{if(version===sessionVersion)void saveDefaults(String(reader.result))};reader.onerror=()=>{if(version===sessionVersion){state.error='Não foi possível ler a imagem.';render()}};reader.readAsDataURL(file)}
async function loadGroups(){const team=state.form.equipe,version=sessionVersion;if(!team){state.error='Selecione a equipe primeiro.';render();return}try{const data=await api('/groups?equipe='+encodeURIComponent(team));if(version!==sessionVersion||team!==state.form.equipe)return;state.groups=data.groups;state.groupsTeam=team;state.groupsVersion=data.version;state.error='';render()}catch(e){if(version===sessionVersion){state.error=e.message;render()}}}
async function saveGroup(){if(state.preferencesBusy)return;const team=state.form.equipe,version=sessionVersion;if(state.groupsTeam!==team){state.error='Carregue os grupos desta equipe primeiro.';render();return}const nome=document.getElementById('group-name').value.trim(),integrantes=clean(state.form.integrantes);if(!nome||!integrantes.length){state.error='Informe o nome do grupo e os integrantes.';render();return}const groups=[...state.groups];const index=groups.findIndex(g=>g.nome===nome);if(index>=0){if(!confirm('Atualizar esse grupo compartilhado para toda a equipe?'))return;groups[index]={nome,integrantes}}else groups.push({nome,integrantes});state.preferencesBusy=true;try{const result=await api('/groups',{method:'PUT',body:JSON.stringify({equipe:team,groups,version:state.groupsVersion})});if(version!==sessionVersion||team!==state.form.equipe)return;state.groups=result.groups;state.groupsVersion=result.version;state.notice='Grupo salvo e disponível para a equipe.';state.error=''}catch(e){if(version===sessionVersion)state.error=e.message}finally{if(version===sessionVersion){state.preferencesBusy=false;render()}}}
function applyGroup(index){if(state.groupsTeam!==state.form.equipe)return;const group=state.groups[index];if(!group)return;if(clean(state.form.integrantes).length&&!confirm('Substituir os integrantes atuais pelos integrantes deste grupo?'))return;state.form.integrantes=[...group.integrantes];markDirty();render()}
function groupsView(){const ready=state.groupsTeam===state.form.equipe;return `<div class="group-panel"><div class="panel-title"><div><label>Grupos da equipe</label><p class="hint">Use grupos compartilhados para preencher a escala em segundos.</p></div><button type="button" onclick="loadGroups()">Atualizar</button></div>${ready?`<div class="stack-row"><select aria-label="Aplicar grupo" onchange="if(this.value!=='')applyGroup(Number(this.value))"><option value="">Selecione um grupo salvo</option>${state.groups.map((g,i)=>`<option value="${i}">${esc(g.nome)} · ${g.integrantes.length} integrantes</option>`).join('')}</select></div><div class="stack-row save-group-row"><input id="group-name" maxlength="120" aria-label="Nome do grupo" placeholder="Nome do grupo, ex.: Plantão diurno"><button ${state.preferencesBusy?'disabled':''} onclick="saveGroup()">Salvar grupo atual</button></div>`:'<p class="hint">Informe a equipe e clique em Atualizar para carregar os grupos disponíveis.</p>'}</div>`}
function preferencesView(){return `<details class="preferences no-print"><summary>Meu preenchimento automático e assinatura</summary><p>O coordenador começa com seu nome de cadastro. Salve equipe e turno atuais para reutilizar no próximo relatório.</p><div class="row"><button ${state.preferencesBusy?'disabled':''} onclick="saveDefaults()">Salvar equipe e turno como padrão</button><label class="signature-upload">Enviar assinatura PNG<input type="file" accept="image/png" ${state.preferencesBusy?'disabled':''} onchange="uploadSignature(this)"></label></div>${state.defaults?.signature?`<img class="signature-image" src="${esc(state.defaults.signature)}" alt="Sua assinatura cadastrada"><button ${state.preferencesBusy?'disabled':''} onclick="saveDefaults('')">Remover assinatura do perfil</button>`:'<p class="hint">Envie sua assinatura em PNG, até 130 KB. Ela será incluída ao salvar o relatório.</p>'}<p class="hint">A imagem identifica o responsável pelo registro; não é uma assinatura digital certificada.</p>${state.notice?`<p role="status">${esc(state.notice)}</p>`:''}</details>`}
function signatureView(){const a=state.form.assinatura;if(!a)return '<p class="hint">Assinatura disponível após salvar o relatório.</p>';return `${a.imagem?`<img class="signature-image" src="${esc(a.imagem)}" alt="Assinatura de ${esc(a.nome)}">`:''}<p class="signature-caption">Registrado por ${esc(a.nome)} · ${esc(a.perfil)}<br>${esc(new Date(a.em).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}))}</p>${state.dirty?'<p class="hint">Há alterações não salvas. A identificação acima corresponde à última versão salva.</p>':''}`}
let securityRequest=0;
function openSecurity(){if(!isChief())return;state.view='security';state.securityOffset=0;render();void loadSecurity()}
async function loadSecurity(offset=state.securityOffset){if(!isChief())return;const session=sessionVersion,request=++securityRequest;state.securityLoading=true;state.securityError='';state.securityUsers=[];state.securityEvents=[];render();try{const [users,audit]=await Promise.all([api('/security/users?offset='+offset),api('/security/audit')]);if(session!==sessionVersion||request!==securityRequest||!isChief())return;state.securityUsers=users.users;state.securityCount=users.count;state.securityEvents=audit.events;state.securityOffset=offset}catch(e){if(session===sessionVersion&&request===securityRequest)state.securityError=e.message}finally{if(session===sessionVersion&&request===securityRequest){state.securityLoading=false;render()}}}

async function createManualBackup(){if(!isChief()||state.securityBusy)return;const session=sessionVersion;state.securityBusy=true;state.securityError='';try{const result=await api('/security/backup',{method:'POST',body:'{}'});if(session===sessionVersion)state.notice='Backup criado: '+result.file}catch(e){if(session===sessionVersion)state.securityError=e.message}finally{if(session===sessionVersion){state.securityBusy=false;render()}}}
async function changeAccess(index,action){if(!isChief()||state.securityBusy)return;const u=state.securityUsers[index];if(!u||u.perfil!=='Supervisor')return;const teams=action==='approve'?document.getElementById('security-teams-'+index).value.split('\n').map(t=>t.trim()).filter(Boolean):[],username=document.getElementById('security-username-'+index)?.value.trim().toLowerCase()||'';if(action==='approve'&&!teams.length){state.securityError='Defina pelo menos uma equipe autorizada.';render();return}if(action==='approve'&&username&&!/^[a-z0-9._-]{3,40}$/.test(username)){state.securityError='Login curto deve ter 3 a 40 letras, numeros, ponto, hifen ou underline.';render();return}if(!confirm(action==='approve'?`Liberar ${u.email} como Supervisor para: ${teams.join(', ')}?`:`Bloquear o acesso de ${u.email} e encerrar suas sessões?`))return;const session=sessionVersion;state.securityBusy=true;state.securityError='';try{await api('/security/users/'+encodeURIComponent(u.id),{method:'PUT',body:JSON.stringify({action,teams,username,version:u.security_version})});if(session===sessionVersion){state.notice=action==='approve'?'Acesso aprovado. A pessoa já pode entrar.':'Acesso bloqueado e sessões encerradas.';await loadSecurity()}}catch(e){if(session===sessionVersion)state.securityError=e.message}finally{if(session===sessionVersion){state.securityBusy=false;render()}}}
function securityView(){if(!isChief())return '';const labels={pending:'Pendente de aprovação',approved:'Aprovado',blocked:'Bloqueado'};return `<nav class="topbar"><div class="brand">Segurança e acessos</div><div class="userbox"><strong>${esc(state.profile.nome)}</strong>Chefia</div><button onclick="state.view='form';render()">Voltar ao plantão</button><button onclick="logout()">Sair</button></nav><main class="wrap workspace"><header class="workspace-heading"><div><div class="kicker">Administração · exclusivo da Chefia</div><h1>Controle de acesso</h1><p>Confira a identidade do solicitante e defina as equipes antes de liberar o acesso.</p></div><div class="row"><button ${state.securityLoading||state.securityBusy?'disabled':''} onclick="loadSecurity()">Atualizar</button><button class="secondary" ${state.securityBusy?'disabled':''} onclick="createManualBackup()">Gerar backup</button></div></header>${state.securityError?`<p class="error" role="alert">${esc(state.securityError)}</p>`:''}${state.notice?`<p role="status">${esc(state.notice)}</p>`:''}<p class="hint">Contas antigas de Supervisor foram colocadas em revisão na atualização de segurança. Os relatórios foram preservados. A equipe solicitada é apenas uma informação do cadastro, não uma autorização.</p>${state.securityLoading?'<p role="status">Carregando acessos...</p>':state.securityUsers.map((u,i)=>`<section class="section security-user"><div><span class="status-pill">${esc(labels[u.access_status]||u.access_status)}</span><h2>${esc(u.nome)}</h2><p>${esc(u.email)} · ${esc(u.perfil)}</p><p class="hint">Equipe solicitada: ${esc(u.requested_team||'Não informada')}<br>Equipes registradas: ${esc(u.teams.join(', ')||'Nenhuma')}<br>Cadastro: ${u.created_at?esc(new Date(u.created_at).toLocaleString('pt-BR')):'Anterior à atualização'}</p></div>${u.perfil==='Supervisor'?`<div><label for="security-username-${i}">Login curto</label><input id="security-username-${i}" maxlength="40" pattern="[a-z0-9._-]{3,40}" value="${esc(u.username||'')}" placeholder="ex.: bruno"><label for="security-teams-${i}">Equipes autorizadas pela Chefia (uma por linha)</label><textarea id="security-teams-${i}" rows="3" placeholder="Informe a equipe após conferir o cadastro">${u.access_status==='approved'?esc(u.teams.join('\n')):''}</textarea><div class="login-actions"><button class="primary" ${state.securityBusy?'disabled':''} onclick="changeAccess(${i},'approve')">${u.access_status==='approved'?'Salvar equipes':'Aprovar acesso'}</button><button class="danger" ${state.securityBusy||u.access_status==='blocked'?'disabled':''} onclick="changeAccess(${i},'block')">Bloquear acesso</button></div></div>`:'<p class="hint">Contas de Chefia são administradas pelo responsável do servidor.</p>'}</section>`).join('')}${!state.securityLoading&&!state.securityError&&!state.securityUsers.length?'<p>Nenhuma conta nesta página.</p>':''}<div class="row"><button ${state.securityLoading||state.securityBusy||state.securityOffset===0?'disabled':''} onclick="loadSecurity(Math.max(0,state.securityOffset-50))">Anterior</button><span>${state.securityCount} contas cadastradas · Página ${Math.floor(state.securityOffset/50)+1}</span><button ${state.securityLoading||state.securityBusy||state.securityOffset+50>=state.securityCount?'disabled':''} onclick="loadSecurity(state.securityOffset+50)">Próxima</button></div><section class="section"><h2>Últimas decisões de acesso</h2><p class="hint">Até 50 decisões recentes, com responsável, data e equipes autorizadas.</p>${state.securityEvents.length?`<div class="security-table"><table><thead><tr><th>Data</th><th>Responsável</th><th>Conta</th><th>Decisão</th><th>Equipes</th></tr></thead><tbody>${state.securityEvents.map(e=>`<tr><td>${esc(new Date(e.occurred_at).toLocaleString('pt-BR'))}</td><td>${esc(e.actor)}</td><td>${esc(e.target)}</td><td>${e.action==='approve'?'Aprovado / equipes atualizadas':'Bloqueado'}</td><td>${esc(JSON.parse(e.next_data).teams.join(', ')||'Nenhuma')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="hint">Nenhuma decisão registrada.</p>'}</section></main>`}
function topbar(){return`<nav class="topbar no-print"><div class="brand">Relatório de Plantão</div><div class="userbox"><strong>${esc(state.profile.nome)}</strong>${esc(state.profile.perfil)}${state.profile.equipe?' - '+esc(state.profile.equipe):''}</div><button onclick="clearForm()">Limpar</button><button onclick="state.view='consolidado';render();void loadRecords()">${isChief()?'Consolidado':'Histórico'}</button>${isChief()?'<button onclick="openSecurity()">Segurança</button>':''}<button onclick="logout()">Sair</button><button class="secondary" onclick="if(state.view!=='consolidado')state.view='report';render();setTimeout(print,120)">Imprimir / PDF</button><button class="primary" onclick="state.view=state.view==='form'?'report':'form';render()">${state.view==='form'?'Gerar relatório':'Voltar à edição'}</button></nav>${state.error?`<p class="error no-print" role="alert">${esc(state.error)}</p>`:''}`}
function listRows(k,p){return state.form[k].map((v,i)=>`<div class="row task-row"><textarea rows="2" placeholder="${p}" oninput="state.form.${k}[${i}]={...state.form.${k}[${i}],texto:this.value}">${esc(taskText(v))}</textarea><select onchange="state.form.${k}[${i}]={...state.form.${k}[${i}],status:this.value};markDirty()"><option ${taskStatus(v)==='Aberto'?'selected':''}>Aberto</option><option ${taskStatus(v)==='Em andamento'?'selected':''}>Em andamento</option><option ${taskStatus(v)==='Resolvido'?'selected':''}>Resolvido</option></select><input placeholder="Responsável" value="${esc(taskOwner(v))}" oninput="state.form.${k}[${i}]={...state.form.${k}[${i}],responsavel:this.value}"><button class="danger" onclick="removeList('${k}',${i})">Remover</button></div>`).join('')}
function setFormTab(tab){state.formTab=tab;render()}
function tabButton(id,label,count){return `<button type="button" class="${state.formTab===id?'selected':''}" aria-pressed="${state.formTab===id}" onclick="setFormTab('${id}')">${label}${count!==undefined?` <span>${count}</span>`:''}</button>`}

function dashboardCards(){const rows=periodRecords(),openTasks=rows.reduce((n,r)=>n+taskCount(r.proximo,'Aberto')+taskCount(r.dia,'Aberto'),0),critical=rows.reduce((n,r)=>n+(r.ocorrencias||[]).filter(o=>o.gravidade==='Alta').length,0),closed=rows.filter(r=>r.fechamento?.em).length;return `<section class="grid5 no-print dashboard-cards"><div class="metric"><strong>${String(rows.length).padStart(2,'0')}</strong><span>Plantões no período</span></div><div class="metric"><strong>${String(openTasks).padStart(2,'0')}</strong><span>Pendências abertas</span></div><div class="metric"><strong>${String(critical).padStart(2,'0')}</strong><span>Ocorrências críticas</span></div><div class="metric"><strong>${String(closed).padStart(2,'0')}</strong><span>Plantões fechados</span></div><div class="metric"><strong>${String(rows.reduce((n,r)=>n+(r.faltas||[]).length,0)).padStart(2,'0')}</strong><span>Faltas registradas</span></div></section>`}
function formTabNav(){const f=state.form;return `<div class="tabs-row no-print"><div class="form-tabs" role="tablist">${tabButton('identificacao','Identificação')}${tabButton('equipe','Equipe',(f.integrantes||[]).filter(x=>String(x).trim()).length)}${tabButton('demandas','Demandas',taskCount(f.dia))}${tabButton('repasses','Repasses',taskCount(f.proximo))}${tabButton('ocorrencias','Ocorrências',(f.ocorrencias||[]).filter(o=>String(o.texto||'').trim()).length)}</div><div class="tab-actions"><span class="save-state">${state.saved?'Salvo':state.dirty?'Alterações pendentes':'Pronto'}</span><button id="save-record" class="primary" ${state.saving?'disabled':''} onclick="saveRecord()">${state.saving?'Salvando...':state.saved?'Salvar novamente':'Salvar plantão'}</button><button class="secondary" ${state.saving||state.form.fechamento?.em?'disabled':''} onclick="closeRecord()">Fechar plantão</button></div></div>`}
function compactFormView(){
  const f=state.form,tab=state.formTab||'identificacao',integrantes=(f.integrantes||[]).filter(x=>String(x).trim()).length;
  const teamField=isChief()?`<input maxlength="120" value="${esc(f.equipe)}" oninput="state.form.equipe=this.value">`:`<select onchange="setForm('equipe',this.value)"><option value="">Selecione uma equipe liberada</option>${state.teams.map(t=>`<option value="${esc(t)}" ${f.equipe===t?'selected':''}>${esc(t)}</option>`).join('')}</select>${!state.teams.length?'<p class="hint">Aguarde a liberacao da sua equipe pela Chefia.</p>':''}`;
  const ident=`<section class="section work-pane overview-pane"><div class="pane-header"><div><div class="kicker">01 - Identificação</div><h2>Dados do plantão</h2></div><span class="status-pill">${f.turno} · ${integrantes} integrantes</span></div><div class="card-grid single-card-grid"><div class="mini-card"><div class="field"><label>Data do plantão</label><input type="date" value="${esc(f.data)}" onchange="setForm('data',this.value)"></div><div class="field"><label>Turno</label><div class="seg pill-seg"><label><input type="radio" name="turno" ${f.turno==='Diurno'?'checked':''} onchange="setForm('turno','Diurno')">Diurno</label><label><input type="radio" name="turno" ${f.turno==='Noturno'?'checked':''} onchange="setForm('turno','Noturno')">Noturno</label></div></div><div class="field"><label>Equipe</label>${teamField}</div><div class="field"><label>Coordenador responsável</label><input value="${esc(f.coordenador)}" oninput="state.form.coordenador=this.value"></div></div></div></section>`;
  const equipe=`<section class="section work-pane grid2"><div><div class="kicker">02 - Grupo e integrantes</div>${groupsView()}${(f.integrantes||[]).map((n,i)=>`<div class="row"><input value="${esc(n)}" placeholder="Nome do integrante" oninput="state.form.integrantes[${i}]=this.value"><button class="danger" onclick="removeList('integrantes',${i})">Remover</button></div>`).join('')}<button class="secondary" onclick="addList('integrantes','')">+ Integrante</button></div><div><div class="kicker">Faltas</div>${(f.faltas||[]).map((x,i)=>`<div class="row"><input placeholder="Nome" value="${esc(x.nome)}" oninput="state.form.faltas[${i}].nome=this.value"><input placeholder="Justificativa" value="${esc(x.motivo)}" oninput="state.form.faltas[${i}].motivo=this.value"><button class="danger" onclick="removeList('faltas',${i})">Remover</button></div>`).join('')}<button class="secondary" onclick="addList('faltas',{nome:'',motivo:''})">+ Falta</button></div></section>`;
  const demandas=`<section class="section work-pane"><div class="kicker">03 - Demandas do dia</div>${listRows('dia','Descreva a demanda executada')}<button class="secondary" onclick="addList('dia',{texto:'',status:'Aberto',responsavel:''})">+ Demanda</button></section>`;
  const repasses=`<section class="section work-pane"><div class="kicker">04 - Próximo plantão</div>${listRows('proximo','Descreva a pendência ou repasse')}<button class="secondary" onclick="addList('proximo',{texto:'',status:'Aberto',responsavel:''})">+ Pendência</button></section>`;
  const ocorrencias=`<section class="section work-pane"><div class="kicker">05 - Ocorrências</div>${(f.ocorrencias||[]).map((o,i)=>`<div class="row occurrence-row"><input type="time" value="${esc(o.hora)}" onchange="state.form.ocorrencias[${i}].hora=this.value"><select onchange="state.form.ocorrencias[${i}].gravidade=this.value"><option ${o.gravidade==='Baixa'?'selected':''}>Baixa</option><option ${o.gravidade==='Media'?'selected':''}>Media</option><option ${o.gravidade==='Alta'?'selected':''}>Alta</option></select><textarea placeholder="Descrição da ocorrência e providências" oninput="state.form.ocorrencias[${i}].texto=this.value">${esc(o.texto)}</textarea><button class="danger" onclick="removeList('ocorrencias',${i})">Remover</button></div>`).join('')}<button class="secondary" onclick="addList('ocorrencias',{hora:'',gravidade:'Baixa',texto:''})">+ Ocorrência</button></section>`;
  return `${topbar()}<main class="wrap workspace compact-workspace"><header class="workspace-heading"><div><div class="kicker">Gestão operacional</div><h1>Painel de plantão</h1><p>Organize sua equipe, registre as atividades e prepare o repasse.</p></div><span class="status-pill">${state.form.fechamento?.em?'Plantão fechado':state.editing?'Editando relatório':'Novo plantão'}</span></header>${dashboardCards()}${formTabNav()}<div class="work-surface">${tab==='equipe'?equipe:tab==='demandas'?demandas:tab==='repasses'?repasses:tab==='ocorrencias'?ocorrencias:ident}</div></main>`;
}
function formView(){const f=state.form;return`${topbar()}<main class="wrap workspace"><header class="workspace-heading"><div><div class="kicker">Gestão operacional</div><h1>Painel de plantão</h1><p>Organize sua equipe, registre as atividades e prepare o repasse.</p></div><span class="status-pill">${state.form.fechamento?.em?'Plantão fechado':state.editing?'Editando relatório':'Novo plantão'}</span></header><section class="section grid2"><div><div class="kicker">01 - Identificação</div><div class="field"><label>Data do plantão</label><input type="date" value="${esc(f.data)}" onchange="setForm('data',this.value)"></div><div class="field"><label>Turno</label><div class="seg"><label><input type="radio" name="turno" ${f.turno==='Diurno'?'checked':''} onchange="setForm('turno','Diurno')">Diurno</label><label><input type="radio" name="turno" ${f.turno==='Noturno'?'checked':''} onchange="setForm('turno','Noturno')">Noturno</label></div></div><div class="field"><label>Equipe</label>${isChief()?`<input maxlength="120" value="${esc(f.equipe)}" oninput="state.form.equipe=this.value">`:`<select onchange="setForm('equipe',this.value)"><option value="">Selecione uma equipe liberada</option>${state.teams.map(t=>`<option value="${esc(t)}" ${f.equipe===t?'selected':''}>${esc(t)}</option>`).join('')}</select>${!state.teams.length?'<p class="hint">Aguarde a liberacao da sua equipe pela Chefia.</p>':''}`}</div><div class="field"><label>Coordenador responsável</label><input value="${esc(f.coordenador)}" oninput="state.form.coordenador=this.value"></div></div><div><div class="kicker">02 - Integrantes e faltas</div>${groupsView()}${(f.integrantes||[]).map((n,i)=>`<div class="row"><input value="${esc(n)}" placeholder="Nome do integrante" oninput="state.form.integrantes[${i}]=this.value"><button class="danger" onclick="removeList('integrantes',${i})">Remover</button></div>`).join('')}<button class="secondary" onclick="addList('integrantes','')">+ Integrante</button><div class="kicker" style="margin-top:24px">Faltas</div>${(f.faltas||[]).map((x,i)=>`<div class="row"><input placeholder="Nome" value="${esc(x.nome)}" oninput="state.form.faltas[${i}].nome=this.value"><input placeholder="Justificativa" value="${esc(x.motivo)}" oninput="state.form.faltas[${i}].motivo=this.value"><button class="danger" onclick="removeList('faltas',${i})">Remover</button></div>`).join('')}<button class="secondary" onclick="addList('faltas',{nome:'',motivo:''})">+ Falta</button></div></section><section class="section grid2"><div><div class="kicker">03 - Demandas do dia</div>${listRows('dia','Descreva a demanda executada')}<button class="secondary" onclick="addList('dia',{texto:'',status:'Aberto',responsavel:''})">+ Demanda</button></div><div><div class="kicker">04 - Próximo plantão</div>${listRows('proximo','Descreva a pendência ou repasse')}<button class="secondary" onclick="addList('proximo',{texto:'',status:'Aberto',responsavel:''})">+ Pendência</button></div></section><section class="section"><div class="kicker">05 - Ocorrências</div>${(f.ocorrencias||[]).map((o,i)=>`<div class="row"><input type="time" value="${esc(o.hora)}" onchange="state.form.ocorrencias[${i}].hora=this.value"><select onchange="state.form.ocorrencias[${i}].gravidade=this.value"><option ${o.gravidade==='Baixa'?'selected':''}>Baixa</option><option ${o.gravidade==='Media'?'selected':''}>Media</option><option ${o.gravidade==='Alta'?'selected':''}>Alta</option></select><textarea placeholder="Descrição da ocorrência e providências" oninput="state.form.ocorrencias[${i}].texto=this.value">${esc(o.texto)}</textarea><button class="danger" onclick="removeList('ocorrencias',${i})">Remover</button></div>`).join('')}<button class="secondary" onclick="addList('ocorrencias',{hora:'',gravidade:'Baixa',texto:''})">+ Ocorrência</button></section></main>`}
function taskTable(rows){rows=cleanTasks(rows);return rows.length?`<table><thead><tr><th>Status</th><th>Responsável</th><th>Registro</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.status)}</td><td>${esc(x.responsavel||'-')}</td><td>${esc(x.texto)}</td></tr>`).join('')}</tbody></table>`:'<p class="hint">Nenhum registro informado.</p>'}
function occTable(rows){return rows.length?`<table><thead><tr><th>Hora</th><th>Gravidade</th><th>Registro</th></tr></thead><tbody>${rows.map(o=>`<tr><td>${esc(o.hora||'-')}</td><td>${esc(o.gravidade)}</td><td>${esc(o.texto)}</td></tr>`).join('')}</tbody></table>`:'<p class="hint">Nenhuma ocorrência registrada neste plantão.</p>'}
function reportView(){const f=state.form,integrantes=clean(f.integrantes),faltas=(f.faltas||[]).filter(x=>String(x.nome||'').trim()),dia=cleanTasks(f.dia),proximo=cleanTasks(f.proximo),ocs=(f.ocorrencias||[]).filter(o=>String(o.texto||'').trim());return`${topbar()}<main class="report"><div class="kicker">Relatório de plantão</div><h1>Plantão ${esc(f.turno.toLowerCase())} - ${esc(longDate(f.data))}</h1><div class="grid3 section"><div><label>Equipe</label>${esc(f.equipe||'-')}</div><div><label>Coordenador responsável</label>${esc(f.coordenador||'-')}</div><div><label>Ocorrências</label>${String(ocs.length).padStart(2,'0')}</div></div><section class="section"><h3>Integrantes</h3>${integrantes.length?integrantes.map(x=>`<span class="tag">${esc(x)}</span>`).join(''):'<p class="hint">Nenhum integrante informado.</p>'}<h3 style="margin-top:22px">Faltas - ${String(faltas.length).padStart(2,'0')}</h3>${faltas.length?faltas.map(x=>`<p><strong>${esc(x.nome)}</strong> - ${esc(x.motivo||'Sem justificativa')}</p>`).join(''):'<p class="hint">Nenhuma falta registrada.</p>'}</section><section class="section grid2"><div><h3>Demandas do dia</h3>${taskTable(dia)}</div><div><h3>Para o próximo plantão</h3>${taskTable(proximo)}</div></section><section class="section"><h3>Ocorrências</h3>${occTable(ocs)}</section><section class="section grid2" style="margin-top:40px"><div><label>Coordenador responsável</label><p><strong>${esc(f.coordenador||'Não informado')}</strong></p>${signatureView()}${f.fechamento?.em?`<p class="status-pill">Plantão fechado por ${esc(f.fechamento.nome)} em ${esc(new Date(f.fechamento.em).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}))}</p>`:''}</div><div><label>Recebido pelo plantão seguinte</label><br><br>________________________________</div></section></main>`}
function consolidatedView(){if(state.recordsLoading||state.recordsError)return `${topbar()}<main class="wrap"><p>${esc(state.recordsError||'Carregando o periodo completo...')}</p><button onclick="void loadRecords()">Atualizar</button></main>`;const rows=periodRecords(),[start,end]=windowDates().map(isoDate),teams=Array.from(new Set(state.records.map(r=>r.equipe).filter(Boolean))).sort(),ocs=rows.flatMap(r=>(r.ocorrencias||[]).map(o=>({...o,data:r.data,turno:r.turno,equipe:r.equipe}))),faltas=rows.flatMap(r=>(r.faltas||[]).map(f=>({...f,data:r.data}))),pend=rows.flatMap(r=>cleanTasks(r.proximo).map(p=>({...p,data:r.data,turno:r.turno,equipe:r.equipe})));return`${topbar()}<main class="wrap"><section class="section"><div class="kicker">Relatório consolidado</div><h1>${state.period==='mes'?`${MESES[parseDate(state.refDate).getMonth()]} de ${parseDate(state.refDate).getFullYear()}`:'Semana operacional'}</h1><p class="hint">${shortDate(start)} a ${shortDate(end)} - ${state.filterTurn.toLowerCase()} - ${state.filterTeam.toLowerCase()}</p><div class="no-print row"><div class="seg"><label><input type="radio" name="period" ${state.period==='semana'?'checked':''} onchange="setValue('period','semana')">Semanal</label><label><input type="radio" name="period" ${state.period==='mes'?'checked':''} onchange="setValue('period','mes')">Mensal</label></div><select onchange="setValue('filterTurn',this.value)"><option>Todos</option><option ${state.filterTurn==='Diurno'?'selected':''}>Diurno</option><option ${state.filterTurn==='Noturno'?'selected':''}>Noturno</option></select><select onchange="setValue('filterTeam',this.value)"><option>Todas as equipes</option>${teams.map(t=>`<option ${state.filterTeam===t?'selected':''}>${esc(t)}</option>`).join('')}</select><input type="date" value="${esc(state.refDate)}" onchange="setValue('refDate',this.value)"></div></section><section class="grid5"><div class="metric"><strong>${String(rows.length).padStart(2,'0')}</strong><span>Plantões</span></div><div class="metric"><strong>${String(rows.filter(r=>r.turno==='Diurno').length).padStart(2,'0')}</strong><span>Diurnos</span></div><div class="metric"><strong>${String(rows.filter(r=>r.turno==='Noturno').length).padStart(2,'0')}</strong><span>Noturnos</span></div><div class="metric"><strong>${String(ocs.length).padStart(2,'0')}</strong><span>Ocorrências</span></div><div class="metric"><strong>${String(faltas.length).padStart(2,'0')}</strong><span>Faltas</span></div></section><section class="section"><h3>Plantões salvos</h3>${rows.length?`<table><thead><tr><th>Data</th><th>Turno</th><th>Equipe</th><th>Coordenador</th><th>Demandas</th><th>Pendências</th><th>Ocorrências</th><th>Faltas</th><th class="no-print">Ação</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${shortDate(r.data)}</td><td>${esc(r.turno)}</td><td>${esc(r.equipe||'-')}</td><td>${esc(r.coordenador||'-')}</td><td>${taskCount(r.dia)}</td><td>${taskCount(r.proximo,'Aberto')}/${taskCount(r.proximo)}</td><td>${(r.ocorrencias||[]).length}</td><td>${(r.faltas||[]).length}</td><td class="no-print action-cell"><button data-open-record="${esc(r.id)}">Abrir</button>${isChief()?`<button data-audit-record="${esc(r.id)}">Auditoria</button>`:''}<button class="danger" data-delete-record="${esc(r.id)}">Excluir</button></td></tr>`).join('')}</tbody></table>`:'<p class="hint">Nenhum plantão salvo neste período.</p>'}</section><section class="section grid2"><div><h3>Ocorrências do periodo</h3>${ocs.length?ocs.map(o=>`<p><strong>${shortDate(o.data)} - ${esc(o.turno)} - ${esc(o.hora||'sem hora')}</strong><br>${esc(o.texto)}</p>`).join(''):'<p class="hint">Sem ocorrências no período.</p>'}</div><div><h3>Repasses registrados no periodo</h3>${pend.length?pend.map(p=>`<p><strong>${shortDate(p.data)} - ${esc(p.turno)} - ${esc(p.equipe||'-')}</strong><br><span class="status-pill">${esc(p.status)}</span> ${esc(p.responsavel?`${p.texto} — ${p.responsavel}`:p.texto)}</p>`).join(''):'<p class="hint">Sem pendências no período.</p>'}</div></section><section class="section"><h3>Faltas do período</h3>${faltas.length?`<table><thead><tr><th>Data</th><th>Nome</th><th>Justificativa</th></tr></thead><tbody>${faltas.map(f=>`<tr><td>${shortDate(f.data)}</td><td>${esc(f.nome)}</td><td>${esc(f.motivo||'Sem justificativa')}</td></tr>`).join('')}</tbody></table>`:'<p class="hint">Nenhuma falta no período.</p>'}<div class="no-print" style="margin-top:24px">${isChief()?`<button class="secondary" ${state.recordsLoading||state.recordsError?'disabled':''} onclick="exportCsv()">Exportar CSV</button>`:''}</div></section>${auditPanel()}</main>`}
function render(){const app=document.getElementById('app');if(state.loading)app.innerHTML='<main class="wrap"><p>Carregando...</p></main>';else if(serverUnavailable)app.innerHTML=setupView();else if(!state.user)app.innerHTML=authView();else if(!state.profile)app.innerHTML=`<main class="wrap"><p>${esc(state.error||'Acesso indisponivel.')}</p><button onclick="logout()">Sair</button></main>`;else if(state.view==='security'&&isChief())app.innerHTML=securityView();else if(state.view==='report')app.innerHTML=reportView();else if(state.view==='consolidado')app.innerHTML=consolidatedView();else app.innerHTML=compactFormView()}
document.addEventListener('input',event=>{if(state.user && event.target.matches('.wrap input,.wrap textarea,.wrap select') && state.view==='form')markDirty()});
document.addEventListener('change',event=>{if(state.user && event.target.matches('.wrap input,.wrap textarea,.wrap select') && state.view==='form')markDirty()});
document.addEventListener('click',event=>{const open=event.target.closest('[data-open-record]');if(open)openRecord(open.dataset.openRecord);const del=event.target.closest('[data-delete-record]');if(del)void deleteRecord(del.dataset.deleteRecord);const aud=event.target.closest('[data-audit-record]');if(aud)void openAudit(aud.dataset.auditRecord)});
window.addEventListener('beforeunload',event=>{if(state.dirty){event.preventDefault();event.returnValue=''}});
if(accountChannel)accountChannel.onmessage=()=>{resetSession();state.loading=true;render();void init()};
window.addEventListener('focus',()=>{if(!state.authBusy)void init()});
init();

